/*
 * RISE Excel export UI.
 * Downloads genuine .xlsx workbooks generated by the API.
 */
(function () {
    "use strict";

    const EXCEL_MIME = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";

    function apiBase() {
        return (window.RISE_API_BASE || "http://localhost:5000") + "/api";
    }

    function authHeaders() {
        const headers = new Headers();
        headers.set("Accept", EXCEL_MIME);
        const token = localStorage.getItem("rise_auth_token");
        if (token) headers.set("Authorization", `Bearer ${token}`);
        return headers;
    }

    async function handleResponse(response) {
        if (response.status === 401) {
            localStorage.removeItem("rise_auth_token");
            localStorage.removeItem("rise_auth_user");
            window.location.href = "login.html";
            throw new Error("Session expired. Please log in again.");
        }
        if (!response.ok) {
            const text = await response.text();
            let problem = null;
            try { problem = text ? JSON.parse(text) : null; } catch (error) { /* keep raw text */ }
            const message = problem?.errors ? Object.values(problem.errors).flat().join(" ")
                : problem?.detail || problem?.title || text || `Request failed (${response.status}).`;
            throw new Error(message);
        }
        return response.blob();
    }

    async function withBusy(button, task) {
        if (!button) return task();
        const original = button.innerHTML;
        button.disabled = true;
        button.innerHTML = `<span class="spinner-border spinner-border-sm me-1" aria-hidden="true"></span>Exporting…`;
        try {
            return await task();
        } finally {
            button.disabled = false;
            button.innerHTML = original;
        }
    }

    function currentFilters(module) {
        const params = new URLSearchParams();
        if (module === "farmers") {
            const search = document.getElementById("searchInput")?.value.trim();
            const sort = document.getElementById("farmerSort")?.value;
            if (search) params.set("search", search);
            if (sort) params.set("sort", sort);
        } else if (module === "supplies") {
            const search = document.getElementById("supplySearch")?.value.trim();
            const sort = document.getElementById("supplySort")?.value;
            if (search) params.set("search", search);
            if (sort) params.set("sort", sort);
        }
        return params.size ? `?${params}` : "";
    }

    async function download(endpoint, filename, button) {
        return withBusy(button, async () => {
            const response = await fetch(`${apiBase()}${endpoint}`, { headers: authHeaders() });
            const blob = await handleResponse(response);
            const url = URL.createObjectURL(blob);
            const link = document.createElement("a");
            link.href = url;
            link.download = filename;
            document.body.appendChild(link);
            link.click();
            link.remove();
            setTimeout(() => URL.revokeObjectURL(url), 30000);
            window.showToast?.("Excel file downloaded.");
        });
    }

    document.addEventListener("click", event => {
        const button = event.target.closest("[data-excel]");
        if (!button) return;
        const action = button.dataset.excel;
        if (action === "farmers-export") download(`/excel/farmers/export${currentFilters("farmers")}`, "Farmer_Records.xlsx", button);
        else if (action === "supplies-export") download(`/excel/supplies/export${currentFilters("supplies")}`, "Supply_Records.xlsx", button);
    });

    window.RISEExcel = { download };
})();
